sed -i '/^resource "terraform_data" "deploy" {$/a\  lifecycle {
    precondition {
      condition     = var.env != "prod" || var.replicas >= 2
      error_message = "prod needs at least 2 replicas."
    }
  }' main.tf

sed -i '/filename = pathexpand("~/shared/upstreams.json")/a\  lifecycle {
    postcondition {
      condition     = length(jsondecode(self.content).upstreams) > 0
      error_message = "The service registry published no upstreams."
    }
  }' main.tf
